<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue'
import {ApiError} from '../../../api/auth'
import {clearMarketReviewOwner} from '../../../stores/marketReviewRecovery'
import {loadReviews,saveReview,getReviewOperation,validReviewNote,validReviewCommand,type ReviewPage,type ReviewState,type ReviewCommand} from '../../../api/marketVersionReview'
import {time} from './marketDataPresentation'
const props=defineProps<{instrumentId:string;versionId:string;actorUserId:string}>()
const emit=defineEmits<{accessDenied:[error:unknown]}>()
const data=ref<ReviewPage|null>(null),loaded=ref(false),busy=ref(false),revoked=ref(false),stale=ref(false),error=ref(''),message=ref(''),pending=ref<string|null>(null)
const pendingCommand=ref<ReviewCommand|null>(null),retryAllowed=ref(false)
const state=ref<ReviewState>('UNREVIEWED'),note=ref(''),confirmed=ref(false)
const labels:Record<ReviewState,string>={UNREVIEWED:'未核对',REVIEWED:'已核对',NEEDS_REVIEW:'需复核'}
let epoch=0,alive=true
function key(){return 'aistock:market-review:'+props.actorUserId+':'+props.instrumentId+':'+props.versionId}
function restore(){pendingCommand.value=null;retryAllowed.value=false;try{const text=sessionStorage.getItem(key());if(!text){pending.value=null;return}let c:unknown;try{c=JSON.parse(text)}catch{c=null}if(validReviewCommand(c)){pendingCommand.value=c;pending.value=c.operationId;note.value=c.note;state.value=c.reviewState}else pending.value=/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/.test(text)?text:null}catch{pending.value=null}}

restore()
function clearPending(){try{sessionStorage.removeItem(key())}catch{}pending.value=null;pendingCommand.value=null;retryAllowed.value=false}
const canSave=computed(()=>loaded.value&&!!data.value&&!busy.value&&!pending.value&&!revoked.value&&confirmed.value&&validReviewNote(note.value.trim()))
function active(n:number){return alive&&n===epoch}
function fail(e:unknown){if(e instanceof ApiError&&(e.status===401||e.status===403&&e.code==='ACCESS_DENIED')){clearMarketReviewOwner(props.actorUserId);clearPending();data.value=null;loaded.value=false;note.value='';confirmed.value=false;message.value='';revoked.value=true;epoch++;busy.value=false;error.value='管理员访问已失效';emit('accessDenied',e);return}error.value=e instanceof Error?e.message:'审核暂无法处理'}
async function load(){if(busy.value||revoked.value)return;const n=epoch;busy.value=true;error.value='';loaded.value=false;try{const p=await loadReviews(props.instrumentId,props.versionId);if(active(n)){data.value=p;loaded.value=true;stale.value=false}}
 catch(e){if(active(n)){stale.value=data.value!==null;fail(e)}}finally{if(active(n))busy.value=false}}
async function save(){if(!canSave.value||!data.value)return;const c:ReviewCommand={operationId:crypto.randomUUID(),expectedRevision:data.value.revision,reviewState:state.value,note:note.value.trim()};try{sessionStorage.setItem(key(),JSON.stringify(c))}catch{error.value='浏览器无法保存操作编号，本次没有提交；请允许本机页面会话存储后重试';return}pendingCommand.value=c;pending.value=c.operationId;await send(c)}
async function retryOriginal(){if(!retryAllowed.value||!pendingCommand.value||busy.value||revoked.value)return;await send(pendingCommand.value)}
async function send(c:ReviewCommand){const n=epoch;retryAllowed.value=false;busy.value=true;loaded.value=false;error.value='';message.value='';
 try{await saveReview(props.instrumentId,props.versionId,c);if(!active(n))return;clearPending();confirmed.value=false;message.value='审核记录已保存';busy.value=false;await load()}
 catch(e){if(!active(n))return;if(e instanceof ApiError&&(e.status===400||e.code==='REVIEW_REVISION_CONFLICT'||e.code==='TASK_ACTION_ORIGIN_DENIED')){clearPending();data.value=null}stale.value=data.value!==null;fail(e)}finally{if(active(n))busy.value=false}}
async function resolve(){if(!pending.value||busy.value||revoked.value)return;const n=epoch,op=pending.value;busy.value=true;error.value='';loaded.value=false;try{await getReviewOperation(props.instrumentId,props.versionId,op);if(!active(n))return;clearPending();confirmed.value=false;message.value='已查询到本次保存结果';busy.value=false;await load()}
 catch(e){if(active(n)){stale.value=data.value!==null;if(e instanceof ApiError&&e.code==='REVIEW_OPERATION_NOT_FOUND'){retryAllowed.value=pendingCommand.value!==null;error.value='目前未查到本次结果，请再次查询，或使用原编号和原命令手动重提；不会新增另一项操作。'}else fail(e)}}finally{if(active(n))busy.value=false}}
watch(()=>[props.actorUserId,props.instrumentId,props.versionId],(next,old)=>{if(next[0]!==old[0]&&old[0])clearMarketReviewOwner(old[0]);epoch++;data.value=null;loaded.value=false;busy.value=false;revoked.value=false;stale.value=false;error.value='';message.value='';note.value='';confirmed.value=false;state.value='UNREVIEWED';restore()})
onUnmounted(()=>{alive=false;epoch++})
</script>
<template><section class="version-review" aria-label="版本审核与处理记录" :aria-busy="busy"><h3>版本审核与处理记录</h3><p>记录管理员的核对进度与依据，不改变行情可用性，也不保证预测准确率。不调用AI或行情数据源。</p><button type="button" data-test="load-reviews" :disabled="busy||revoked" @click="load">{{data?'刷新审核记录':'查看审核记录'}}</button><p v-if="busy" role="status">正在处理，请勿重复提交…</p><p v-if="error" role="alert">{{error}}<span v-if="stale"> · 原记录未刷新，保留原查询时间。</span></p><p v-if="message" role="status">{{message}}</p><div v-if="pending" class="review-warning"><p>待核对操作编号：{{pending}}</p><p>保存结果尚未确认；查询不会再次提交。原命令仅保存在当前浏览器会话，核对完成后清除。暂未查到不代表原请求不会稍后完成。</p><button type="button" data-test="resolve-review" :disabled="busy||revoked" @click="resolve">查询本次保存结果</button><button v-if="retryAllowed&&pendingCommand" type="button" data-test="retry-review" :disabled="busy||revoked" @click="retryOriginal">使用原编号再次保存</button></div><template v-if="data"><p>当前审核标记：{{data.current?labels[data.current.reviewState]:'未核对'}} · 审核修订：{{data.revision}}</p><p v-if="data.current">说明：{{data.current.note}}</p><p class="md-muted">查询时间：{{time(data.queriedAt)}}</p></template><div class="review-fields"><label>审核标记<select v-model="state" :disabled="busy||revoked||!!pending"><option value="UNREVIEWED">未核对</option><option value="REVIEWED">已核对</option><option value="NEEDS_REVIEW">需复核</option></select></label><label>核对说明<textarea v-model="note" maxlength="300" rows="3" :disabled="busy||revoked||!!pending" placeholder="填写核对依据或需要复核的问题，不要填写密码或密钥。"/></label><p>{{note.length}} / 300 字</p><label class="review-confirm"><input v-model="confirmed" type="checkbox" :disabled="busy||revoked||!!pending">我确认本次只记录审核进度，不改变行情版本的可用状态。</label><button type="button" data-test="save-review" :disabled="!canSave" @click="save">保存审核记录</button><p v-if="!loaded&&!pending" class="md-muted">请先成功加载审核记录，再填写说明并保存。</p></div><details v-if="data"><summary>审核历史（最近20条）</summary><p v-if="!data.history.length">暂无审核记录。</p><ol v-else><li v-for="r in data.history" :key="r.operationId"><p>{{labels[r.reviewState]}} · 修订 {{r.revision}} · {{time(r.createdAt)}}</p><p class="review-note">{{r.note}}</p><p class="md-muted">操作编号：{{r.operationId}}</p></li></ol><p v-if="data.hasMore">还有更早审核记录，服务端保留完整历史；本区仅展示最近20条。</p></details></section></template>
<style scoped>.version-review{border:1px solid var(--border);border-radius:8px;padding:16px;margin:16px 0;overflow-wrap:anywhere}.review-fields{display:grid;gap:12px;margin:16px 0}.review-fields label:not(.review-confirm){display:grid;gap:8px}.review-fields textarea,.review-fields select{box-sizing:border-box;max-width:100%;width:100%}.review-fields textarea{resize:vertical}.review-confirm{display:flex;align-items:flex-start;gap:8px;line-height:1.6}.review-confirm input{flex:none;width:auto;margin-top:5px}.review-warning{border-left:3px solid var(--accent);padding:8px 12px;background:var(--canvas)}.review-note{white-space:pre-wrap}.version-review button:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.version-review ol{padding-left:22px}.review-fields button{justify-self:start}</style>
